class Solution {
    public int minDistance(String word1, String word2) {
        return dfs(word1, word2, 0, 0);
    }
    private int dfs(String a, String b, int i, int j) {
        if (i == a.length()) return b.length() - j;
        if (j == b.length()) return a.length() - i;
        if (a.charAt(i) == b.charAt(j)) return dfs(a, b, i + 1, j + 1);
        int insertOp = dfs(a, b, i, j + 1);
        int deleteOp = dfs(a, b, i + 1, j);
        int replaceOp = dfs(a, b, i + 1, j + 1);
        return 1 + Math.min(insertOp, Math.min(deleteOp, replaceOp));
    }
}

